        "Görüşmede yalnızca şikâyet değil, kişinin günü de dinlenir. Mesleği, günlük hareketliliği, uyku düzeni, spor ya da yürüyüş alışkanlığı ve evdeki yaşam koşulları değerlendirmenin yönünü belirleyen bilgilerdir. Aynı ağrıyı tarif eden iki kişinin gün akışı çoğu zaman birbirinden çok farklı olabilir. Örneğin sabah ilk adımlarda beliren bir tutukluk ile akşama doğru artan bir yorgunluk his olarak benzer görünse de farklı yönlerde değerlendirilir.",
